// Sample only (Nov 11 2026, Adam: "let's do it better and let's make it look so much better as well. I am 100% OK if it is
// 100% generated by AI"). Lays a proposal out as a Word document from content.json (written by an AI model from the RFP,
// the requirement list and the tool's catalog). Nothing in the tool is changed.
//   node sow/proposal_sample/build_docx.js <content.json> <out.docx>
const fs = require('fs');
const D = require('docx');
const {Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle, AlignmentType, HeadingLevel, LevelFormat, Footer, Header, PageNumber, PageBreak, ExternalHyperlink, VerticalAlign, TableLayoutType} = D;
const C = JSON.parse(fs.readFileSync(process.argv[2], 'utf8')), OUT = process.argv[3];
const RED = 'EB1000', INK = '1C1C1C', RULE = 'C9C9C9', PALE = 'F4F4F4', FIELD = 'FFF1A8', FONT = 'Arial';
const W = 12240 - 2 * 1080;   // text width on US Letter with 0.75 inch margins
if (/[–—]/.test(JSON.stringify(C))) throw new Error('a dash in the content');

// inline text: [12] is a source number (small, red, raised); [A FIELD TO FILL IN] is marked for the partner
function runs(text, o = {}) { const out = []; let last = 0; const s = String(text == null ? '' : text);
  for (const m of s.matchAll(/\[(\d{1,3}(?:,\s*\d{1,3})*)\]|\[([A-Z][A-Z0-9 ,.'\/&()-]{2,})\]/g)) {
    if (m.index > last) out.push(new TextRun(Object.assign({text: m[1] ? s.slice(last, m.index).replace(/\s+$/, '') : s.slice(last, m.index), font: FONT}, o)));   // a source number sits against its word
    if (m[1]) out.push(new TextRun(Object.assign({}, o, {text: m[1].replace(/\s+/g, ''), font: FONT, superScript: true, color: RED, bold: true})));
    else out.push(new TextRun(Object.assign({}, o, {text: '[' + m[2] + ']', font: FONT, bold: true, shading: {type: ShadingType.CLEAR, fill: FIELD, color: 'auto'}})));
    last = m.index + m[0].length; }
  if (last < s.length) out.push(new TextRun(Object.assign({text: s.slice(last), font: FONT}, o)));
  return out; }
const P = (text, o = {}, ro = {}) => new Paragraph(Object.assign({children: runs(text, Object.assign({size: 21, color: INK}, ro)), spacing: {before: 0, after: 140, line: 300}}, o));
const none = {style: BorderStyle.NONE, size: 0, color: 'FFFFFF'}, thin = {style: BorderStyle.SINGLE, size: 4, color: RULE};
const cell = (children, w, o = {}) => new TableCell(Object.assign({children, width: {size: w, type: WidthType.DXA}, margins: {top: 90, bottom: 90, left: 130, right: 130}, verticalAlign: VerticalAlign.TOP}, o));

function table(b) { const n = b.columns.length, ws = (b.widths && b.widths.length === n ? b.widths : Array(n).fill(100 / n)).map(x => Math.round(W * x / 100)); ws[n - 1] += W - ws.reduce((a, x) => a + x, 0);
  const head = new TableRow({tableHeader: true, cantSplit: true, children: b.columns.map((c, i) => cell([new Paragraph({children: [new TextRun({text: String(c), font: FONT, bold: true, size: 18, color: 'FFFFFF'})], spacing: {before: 0, after: 0}})], ws[i], {shading: {type: ShadingType.CLEAR, fill: INK, color: 'auto'}, borders: {top: none, bottom: none, left: none, right: none}}))});
  const rows = b.rows.map(r => { const total = /^total\b/i.test(String(r[0] || ''));
    return new TableRow({cantSplit: true, children: b.columns.map((_, i) => cell([new Paragraph({children: runs(r[i], {size: 19, color: INK, bold: total || (i === 0 && n > 2)}), spacing: {before: 0, after: 0, line: 270}})], ws[i], {shading: total ? {type: ShadingType.CLEAR, fill: PALE, color: 'auto'} : undefined, borders: {top: none, left: none, right: none, bottom: thin}}))}); });
  return [new Table({width: {size: W, type: WidthType.DXA}, columnWidths: ws, layout: TableLayoutType.FIXED, rows: [head, ...rows]}), new Paragraph({children: [], spacing: {before: 0, after: 160}})]; }
function callout(b) { const edge = {style: BorderStyle.SINGLE, size: 6, color: INK};
  return [new Table({width: {size: W, type: WidthType.DXA}, columnWidths: [W], layout: TableLayoutType.FIXED, rows: [new TableRow({cantSplit: true, children: [cell([
    new Paragraph({children: [new TextRun({text: String(b.title || '').toUpperCase(), font: FONT, bold: true, size: 17, color: RED, characterSpacing: 30})], spacing: {before: 0, after: 60}}),
    new Paragraph({children: runs(b.text, {size: 20, color: INK}), spacing: {before: 0, after: 0, line: 290}})], W,
    {margins: {top: 160, bottom: 160, left: 220, right: 220}, borders: {top: edge, bottom: edge, right: edge, left: {style: BorderStyle.SINGLE, size: 36, color: RED}}})]})]}), new Paragraph({children: [], spacing: {before: 0, after: 160}})]; }
function block(b) {
  if (b.type === 'p') return [P(b.text)];
  if (b.type === 'h2') return [new Paragraph({heading: HeadingLevel.HEADING_2, children: [new TextRun({text: b.text, font: FONT, bold: true, size: 25, color: INK})]})];
  if (b.type === 'bullets') return b.items.map(t => new Paragraph({numbering: {reference: 'dots', level: 0}, children: runs(t, {size: 21, color: INK}), spacing: {before: 0, after: 90, line: 300}}));
  if (b.type === 'table') return table(b);
  if (b.type === 'callout') return callout(b);
  throw new Error('unknown block ' + b.type); }

const m = C.meta, body = [];
// the cover
body.push(new Paragraph({children: [new TextRun({text: 'PROPOSAL', font: FONT, bold: true, size: 20, color: 'FFFFFF', characterSpacing: 60})], shading: {type: ShadingType.CLEAR, fill: RED, color: 'auto'}, spacing: {before: 0, after: 0}, indent: {left: 160}, border: {top: {style: BorderStyle.SINGLE, size: 48, color: RED, space: 6}, bottom: {style: BorderStyle.SINGLE, size: 48, color: RED, space: 6}}}));
body.push(new Paragraph({children: [], spacing: {before: 1500, after: 0}}));
body.push(new Paragraph({children: [new TextRun({text: m.title, font: FONT, bold: true, size: 64, color: INK})], spacing: {before: 0, after: 240, line: 700}}));
body.push(new Paragraph({children: [new TextRun({text: m.client, font: FONT, size: 30, color: INK})], spacing: {before: 0, after: 60}}));
if (m.client_unit) body.push(new Paragraph({children: [new TextRun({text: m.client_unit, font: FONT, size: 24, color: INK})], spacing: {before: 0, after: 600}}));
const metaRow = (k, v) => new TableRow({children: [cell([new Paragraph({children: [new TextRun({text: k.toUpperCase(), font: FONT, bold: true, size: 16, color: RED, characterSpacing: 30})], spacing: {before: 0, after: 0}})], 2600, {borders: {top: thin, bottom: none, left: none, right: none}}),
  cell([new Paragraph({children: runs(v, {size: 21, color: INK}), spacing: {before: 0, after: 0}})], W - 2600, {borders: {top: thin, bottom: none, left: none, right: none}})]});
body.push(new Table({width: {size: W, type: WidthType.DXA}, columnWidths: [2600, W - 2600], layout: TableLayoutType.FIXED, rows: [metaRow('Solicitation', m.solicitation), metaRow('Project', m.project), metaRow('Prepared by', m.prepared_by), metaRow('Date', m.date)]}));
body.push(new Paragraph({children: [], spacing: {before: 500, after: 0}}));
for (const n of C.notices || []) body.push(...callout({title: 'Read first', text: n}));
body.push(new Paragraph({children: [new PageBreak()]}));
// at a glance
body.push(new Paragraph({children: [new TextRun({text: 'AT A GLANCE', font: FONT, bold: true, size: 18, color: RED, characterSpacing: 40})], spacing: {before: 0, after: 80}}));
body.push(new Paragraph({children: [new TextRun({text: 'What this proposal delivers', font: FONT, bold: true, size: 40, color: INK})], spacing: {before: 0, after: 260}}));
{ const s = C.glance.stats, w = Math.floor(W / s.length), ws = s.map((_, i) => i === s.length - 1 ? W - w * (s.length - 1) : w);
  body.push(new Table({width: {size: W, type: WidthType.DXA}, columnWidths: ws, layout: TableLayoutType.FIXED, rows: [new TableRow({children: s.map((x, i) => cell([
    new Paragraph({children: [new TextRun({text: String(x.value), font: FONT, bold: true, size: 60, color: RED})], spacing: {before: 0, after: 40}}),
    new Paragraph({children: [new TextRun({text: String(x.label), font: FONT, size: 19, color: INK})], spacing: {before: 0, after: 0, line: 270}})], ws[i],
    {margins: {top: 180, bottom: 180, left: 180, right: 140}, borders: {top: {style: BorderStyle.SINGLE, size: 18, color: INK}, bottom: thin, left: none, right: none}}))})]}));
  body.push(new Paragraph({children: [], spacing: {before: 0, after: 260}})); }
for (const o of C.glance.outcomes) body.push(new Paragraph({numbering: {reference: 'dots', level: 0}, children: runs(o, {size: 23, color: INK}), spacing: {before: 0, after: 130, line: 320}}));
body.push(new Paragraph({children: [new TextRun({text: 'CONTENTS', font: FONT, bold: true, size: 18, color: RED, characterSpacing: 40})], spacing: {before: 420, after: 120}}));
for (const s of C.sections) body.push(new Paragraph({children: [new TextRun({text: s.number + '   ', font: FONT, bold: true, size: 21, color: RED}), new TextRun({text: s.title, font: FONT, size: 21, color: INK})], spacing: {before: 0, after: 70}, border: {bottom: {style: BorderStyle.SINGLE, size: 4, color: RULE, space: 3}}}));
// the sections
for (const s of C.sections) {
  body.push(new Paragraph({heading: HeadingLevel.HEADING_1, pageBreakBefore: true, children: [new TextRun({text: s.number + '  ', font: FONT, bold: true, size: 36, color: RED}), new TextRun({text: s.title, font: FONT, bold: true, size: 36, color: INK})]}));
  for (const b of s.blocks) body.push(...block(b)); }
// sources
body.push(new Paragraph({heading: HeadingLevel.HEADING_1, pageBreakBefore: true, children: [new TextRun({text: 'Adobe sources', font: FONT, bold: true, size: 36, color: INK})]}));
body.push(P('Every statement about an Adobe product in this proposal rests on one of these public Adobe pages. The small red numbers in the text point here.'));
for (const x of C.sources) body.push(new Paragraph({children: [new TextRun({text: x.n + '   ', font: FONT, bold: true, size: 19, color: RED}), new ExternalHyperlink({link: x.url, children: [new TextRun({text: x.title, font: FONT, size: 19, color: INK, underline: {}})]})], spacing: {before: 0, after: 80}, indent: {left: 420, hanging: 420}}));

const doc = new Document({creator: m.prepared_by, title: m.title,
  styles: {default: {document: {run: {font: FONT, size: 21}},
    heading1: {run: {font: FONT, size: 36, bold: true, color: INK}, paragraph: {spacing: {before: 0, after: 220}, keepNext: true}},
    heading2: {run: {font: FONT, size: 25, bold: true, color: INK}, paragraph: {spacing: {before: 260, after: 110}, keepNext: true}}}},
  numbering: {config: [{reference: 'dots', levels: [{level: 0, format: LevelFormat.BULLET, text: '•', alignment: AlignmentType.LEFT, style: {paragraph: {indent: {left: 360, hanging: 240}}, run: {color: RED, font: FONT}}}]}]},
  sections: [{properties: {page: {size: {width: 12240, height: 15840}, margin: {top: 1080, bottom: 1080, left: 1080, right: 1080}}, titlePage: true},
    headers: {default: new Header({children: [new Paragraph({children: [new TextRun({text: m.title, font: FONT, size: 16, color: INK})], alignment: AlignmentType.RIGHT, border: {bottom: {style: BorderStyle.SINGLE, size: 4, color: RULE, space: 4}}})]}), first: new Header({children: [new Paragraph({children: []})]})},
    footers: {default: new Footer({children: [new Paragraph({children: [new TextRun({text: m.client + '   |   ' + m.solicitation + '   |   Draft for review   |   Page ', font: FONT, size: 16, color: INK}), new TextRun({children: [PageNumber.CURRENT], font: FONT, size: 16, color: INK})]})]}), first: new Footer({children: [new Paragraph({children: []})]})},
    children: body}]});
Packer.toBuffer(doc).then(buf => { fs.writeFileSync(OUT, buf); console.log('written', OUT, buf.length, 'bytes'); });
